pthread_mutex_lock(&g->mu);
f = map_get(&g, key);
if (f) {                                      /* waiter: join the flight */
    f->waiters++; while (!f->done) pthread_cond_wait(&f->cv, &g->mu);
    copy_out(f, out); f->waiters--;
} else {                                      /* leader: register, then run */
    f = flight_new(); map_put(&g, key, f);
    pthread_mutex_unlock(&g->mu);
    flight_run(f, load, key);                 /* exactly one execution */
    pthread_mutex_lock(&g->mu);
    map_del(&g, key); f->done = 1; pthread_cond_broadcast(&f->cv); /* forget */
}
pthread_mutex_unlock(&g->mu);                 /* reclaim f when waiters == 0 */
